import { Platform } from "react-native";
import * as Notifications from "expo-notifications";
import AsyncStorage from "@react-native-async-storage/async-storage";
import Constants from "expo-constants";

const PUSH_TOKEN_KEY = "@store_push_token";

/**
 * Register for push notifications and return the Expo push token
 */
export async function registerForPushNotifications(): Promise<string | null> {
  try {
    const settings = await Notifications.getPermissionsAsync();

    if (!settings.granted) {
      if (settings.status === "denied") {
        console.warn("⚠️ Notification permission denied — enable in Settings");
        return null;
      }

      const permission = await Notifications.requestPermissionsAsync({
        ios: { allowAlert: true, allowBadge: true, allowSound: true },
      });
      if (!permission.granted) {
        console.warn("⚠️ Notification permission not granted");
        return null;
      }
    }

    const projectId =
      Constants.easConfig?.projectId ||
      Constants.expoConfig?.extra?.eas?.projectId;
    if (!projectId) {
      console.warn("⚠️ EAS projectId not configured — push tokens unavailable");
      return null;
    }

    const token = (await Notifications.getExpoPushTokenAsync({ projectId }))
      .data;
    console.log("✅ Store push token:", token);

    // Create Android channels
    if (Platform.OS === "android") {
      await Notifications.setNotificationChannelAsync("incoming-orders", {
        name: "Incoming Orders",
        importance: Notifications.AndroidImportance.MAX,
        vibrationPattern: [0, 500, 200, 500, 200, 500],
        lockscreenVisibility: Notifications.AndroidNotificationVisibility.PUBLIC,
        sound: "default",
        bypassDnd: true,
        enableVibrate: true,
        lightColor: "#E23744",
      });
      await Notifications.setNotificationChannelAsync("orders", {
        name: "Orders",
        importance: Notifications.AndroidImportance.MAX,
        vibrationPattern: [0, 400, 250, 400, 250, 400],
        lockscreenVisibility: Notifications.AndroidNotificationVisibility.PUBLIC,
        sound: "default",
        bypassDnd: true,
        lightColor: "#E23744",
      });
      await Notifications.setNotificationChannelAsync("ongoing-orders", {
        name: "Ongoing Order Activity",
        importance: Notifications.AndroidImportance.MAX,
        lockscreenVisibility: Notifications.AndroidNotificationVisibility.PUBLIC,
        sound: "default",
        bypassDnd: true,
        vibrationPattern: [0, 250, 150, 250],
      });
      await Notifications.setNotificationChannelAsync("default", {
        name: "Default",
        importance: Notifications.AndroidImportance.HIGH,
        vibrationPattern: [0, 250, 250, 250],
      });
    }

    await AsyncStorage.setItem(PUSH_TOKEN_KEY, token);
    return token;
  } catch (err) {
    console.error("❌ Push registration failed:", err);
    return null;
  }
}

export async function getPushTokenLocally(): Promise<string | null> {
  return AsyncStorage.getItem(PUSH_TOKEN_KEY);
}
